def parse_sensor_reading(data):
    """
    Parses a sensor reading string in the format "T:<temp>|H:<humidity>|TS:<timestamp>"
    and returns a dict with keys "temperature" (float or None), "humidity" (int or None),
    and "timestamp" (int or None). Extra or malformed fields are ignored.
    """
    result = {"temperature": None, "humidity": None, "timestamp": None}
    if not isinstance(data, str):
        return result
    if not data.strip():
        return result

    parts = data.split("|")
    for part in parts:
        if ":" not in part:
            continue
        key, val = part.split(":", 1)
        key = key.strip()
        val = val.strip()
        if key == "T":
            try:
                result["temperature"] = float(val)
            except (ValueError, TypeError):
                result["temperature"] = None
        elif key == "H":
            try:
                result["humidity"] = int(val)
            except (ValueError, TypeError):
                result["humidity"] = None
        elif key == "TS":
            try:
                result["timestamp"] = int(val)
            except (ValueError, TypeError):
                result["timestamp"] = None
    return result

